const isObject = value => typeof value === 'object' && value !== null && !Array.isArray(value);
const nonBlank = value => typeof value === 'string' && /\S/.test(value);
const hasShape = (value, required, optional = []) => isObject(value) &&
  required.every(key => Object.hasOwn(value, key)) &&
  Object.keys(value).every(key => required.includes(key) || optional.includes(key));
const stringList = value => Array.isArray(value) &&
  value.every(nonBlank) && new Set(value).size === value.length;
const validPermissions = value => hasShape(value, ['scopes'], ['entitlements', 'consents']) &&
  Object.values(value).every(stringList);
const channels = ['webhook', 'email', 'whatsapp', 'telegram'];
const items = $input.all();
const request = items.length === 1 ? items[0].json : undefined;
const attachmentValid = file => hasShape(file, ['attachment_id'], ['name', 'media_type']) &&
  Object.values(file).every(nonBlank);
const requestId = nonBlank(request?.request_id) ? request.request_id : null;
const channel = channels.includes(request?.channel) ? request.channel : null;
const required = ['user_id', 'conversation_id', 'channel', 'message', 'attachments', 'locale', 'request_id', 'permission_context'];
const valid = hasShape(request, required) &&
  [request.user_id, request.conversation_id, request.locale].every(nonBlank) &&
  requestId !== null && channel !== null &&
  typeof request.message === 'string' &&
  Array.isArray(request.attachments) && request.attachments.every(attachmentValid) &&
  (nonBlank(request.message) || request.attachments.length > 0) &&
  validPermissions(request.permission_context);

if (!valid) {
  return [{ json: { status: 'invalid_request', request_id: requestId, channel,
    reply: 'Заявката не отговаря на изискванията на Shark AI.' } }];
}
if (request.message.length > 16000) {
  return [{ json: { status: 'invalid_request', request_id: requestId, channel,
    reply: 'Съобщението надвишава 16 000 знака. Изпратете го на части.' } }];
}
if (!nonBlank(request.message)) {
  return [{ json: { status: 'needs_human', request_id: requestId, channel,
    reply: 'Прикаченият файл не е достъпен. Изпратете нужната информация като текст.' } }];
}

return [{ json: { route: 'agent', request_id: requestId, channel,
  locale: request.locale.slice(0, 64), message: request.message,
  attachment_count: request.attachments.length,
  router_context: {
    user_id: request.user_id, conversation_id: request.conversation_id, channel, request_id: requestId,
    permission_context: { scopes: request.permission_context.scopes },
  } } }];

const original = $('Провери заявката').first().json;
const expose = (status, reply) => [{ json: { status, request_id: original.request_id,
  channel: original.channel, reply } }];
const unavailable = 'Shark AI не успя да обработи заявката. Опитайте отново.';
const items = $input.all();
if (items.length !== 1 || typeof items[0].json.output !== 'string') {
  return expose('unavailable', unavailable);
}

let response;
try {
  const text = items[0].json.output.trim();
  const fenced = text.match(/^\x60{3}(?:json)?\s*([\s\S]*?)\s*\x60{3}$/i);
  response = JSON.parse(fenced ? fenced[1] : text);
} catch {
  return expose('unavailable', unavailable);
}
if (!response || typeof response !== 'object' || Array.isArray(response) ||
    Object.keys(response).sort().join(',') !== 'intent,reply' ||
    !['question', 'draft', 'automation_draft', 'human_review'].includes(response.intent) ||
    typeof response.reply !== 'string' || !response.reply.trim() || response.reply.length > 16000) {
  return expose('unavailable', unavailable);
}

return expose(response.intent === 'human_review' ? 'needs_human' : 'ok', response.reply.trim());
